"""
frontend_assets.py - Self-healing embedded frontend assets for News Monitor.
Guarantees the application never crashes with TemplateNotFound even if templates/static
directories are not present in a fresh clone.
"""

import os
import base64

INDEX_HTML_B64 = ""
STYLE_CSS_B64 = ""
APP_JS_B64 = ""

def ensure_frontend_files():
    """Restores templates/index.html, static/style.css, and static/app.js if missing."""
    base_dir = os.path.dirname(os.path.abspath(__file__))
    templates_dir = os.path.join(base_dir, "templates")
    static_dir = os.path.join(base_dir, "static")
    index_path = os.path.join(templates_dir, "index.html")
    css_path = os.path.join(static_dir, "style.css")
    js_path = os.path.join(static_dir, "app.js")

    os.makedirs(templates_dir, exist_ok=True)
    os.makedirs(static_dir, exist_ok=True)

    if not os.path.exists(index_path):
        with open(index_path, "wb") as f:
            f.write(base64.b64decode(INDEX_HTML_B64))

    if not os.path.exists(css_path):
        with open(css_path, "wb") as f:
            f.write(base64.b64decode(STYLE_CSS_B64))

    if not os.path.exists(js_path):
        with open(js_path, "wb") as f:
            f.write(base64.b64decode(APP_JS_B64))

# Auto-execute on import
ensure_frontend_files()
